class Solution {
    List<List<String>> res = new ArrayList<>();
    public List<List<String>> solveNQueens(int n) {
        char[][] chessboard = new char[n][n];
        for (char[] item : chessboard) {
            Arrays.fill(item, '.');
        }
        backtracking(chessboard,0);
        return res;
    }
    private void backtracking(char[][] chessboard, int row) {
        if (row == chessboard.length) {
            addToRes(chessboard);
            return;
        }
        for (int col = 0; col < chessboard[0].length; col++) {
            if (isVaild(chessboard, row, col)) {
                chessboard[row][col] = 'Q';
                backtracking(chessboard, row + 1);
                chessboard[row][col] = '.';
            }
        }
    }
    private boolean isVaild(char[][] chessboard, int row, int col) {
        for(int i = 0;i<chessboard.length;i++){
            if(chessboard[i][col]=='Q')
            return false;
        }
        for(int i = row-1,j = col-1;i>=0 && j>=0;i--,j--){
            if(chessboard[i][j]=='Q')
            return false;
        }
        for(int i = row-1,j = col + 1; i>=0&&j<chessboard[0].length ;i--,j++){
            if(chessboard[i][j]=='Q')
            return false;
        }
        return true;
    }
    private void addToRes(char[][]chessboard){
        List<String> path = new ArrayList<>();
        for(char[]item:chessboard){
            StringBuilder sb = new StringBuilder();
            for(char c:item){
                sb.append(c);
            }
            path.add(sb.toString());
        }
        res.add(path);
    }
}
